using Microsoft.WindowsAzure.Storage;
using Microsoft.WindowsAzure.Storage.Auth;
using Microsoft.WindowsAzure.Storage.Blob;

/// <summary>
/// Code extensions for the <c>SrsReportRunMailer</c> class.
/// </summary>
[ExtensionOf(classStr(SrsReportRunMailer))]
final class KPMGSrsReportRunMailer_Extension
{
    
    internal    SRSCatalogItemName  kpmgReportName;
    internal    Filename            kpmgFileName;
    internal    str                 kpmgReportRecordNum;
    internal    SysEmailId          kpmgSysEmailId;
    internal    str                 kpmgFromAddress;
    internal    SysEmailSubject     kpmgSysEmailSubject;
    internal    SysEmailContents    kpmgSysEmailContents;
    internal    str                 kpmgBlobAccountName, kpmgBlobAccountKey;
    internal    KPMGBlobContainerName kpmgBlobContainerName;

}

Method.Source:
    /// <summary>
    /// Current report name
    /// </summary>
    /// <param name = "_reportName">Report name</param>
    /// <returns>Report name</returns>
    public SRSCatalogItemName parmKPMGReportName(SRSCatalogItemName _reportName = kpmgReportName)
    {
        kpmgReportName = _reportName;

        return kpmgReportName;
    }

    /// <summary>
    /// File name of the attachment
    /// </summary>
    /// <param name = "_fileName">File name of the attachment</param>
    /// <returns>File name of the attachment</returns>
    public Filename parmKPMGFileName(Filename _fileName = kpmgFileName)
    {
        kpmgFileName = _fileName;

        return kpmgFileName;
    }

    /// <summary>
    /// Email template Id
    /// </summary>
    /// <param name = "_sysEmailId">Email template Id</param>
    /// <returns>Email template Id</returns>
    public SysEmailId parmKPMGSysEmailId(SysEmailId _sysEmailId = kpmgSysEmailId)
    {
        kpmgSysEmailId = _sysEmailId;

        return kpmgSysEmailId;
    }

    /// <summary>
    /// From email address
    /// </summary>
    /// <param name = "_fromAddress">From email address</param>
    /// <returns>From email address of type str</returns>
    public str parmKPMGFromAddress(str _fromAddress = kpmgFromAddress)
    {
        kpmgFromAddress = _fromAddress;

        return kpmgFromAddress;
    }

    /// <summary>
    /// Email subject
    /// </summary>
    /// <param name = "_kpmgSysEmailSubject">Email subject</param>
    /// <returns>Email subject</returns>
    public SysEmailSubject parmKPMGSysEmailSubject(SysEmailSubject _kpmgSysEmailSubject = kpmgSysEmailSubject)
    {
        kpmgSysEmailSubject = _kpmgSysEmailSubject;

        return kpmgSysEmailSubject;
    }

    /// <summary>
    /// Email contents
    /// </summary>
    /// <param name = "_kpmgSysEmailContents">Email contents</param>
    /// <returns>Email contents</returns>
    public SysEmailContents parmKPMGSysEmailContents(SysEmailContents _kpmgSysEmailContents = kpmgSysEmailContents)
    {
        kpmgSysEmailContents = _kpmgSysEmailContents;

        return kpmgSysEmailContents;
    }

    /// <summary>
    /// report record number
    /// </summary>
    /// <param name = "_kpmgReportRecordNum">report record number</param>
    /// <returns>report record number</returns>
    public str parmKPMGReportRecordNum(str _kpmgReportRecordNum = kpmgReportRecordNum)
    {
        kpmgReportRecordNum = _kpmgReportRecordNum;

        return kpmgReportRecordNum;
    }

/// <summary>
/// Blob account name
/// </summary>
/// <param name = "_kpmgBlobAccountName">Blob account name</param>
/// <returns>Record of type str</returns>
public str parmKPMGBlobAccountName(str _kpmgBlobAccountName = kpmgBlobAccountName)
{
    kpmgBlobAccountName = _kpmgBlobAccountName;
     
    return kpmgBlobAccountName;
}

/// <summary>
/// Blob account key
/// </summary>
/// <param name = "_kpmgBlobAccountKey">Blob account key</param>
/// <returns>Record of type str</returns>
public str parmKPMGBlobAccountKey(str _kpmgBlobAccountKey = kpmgBlobAccountKey)
{
    kpmgBlobAccountKey = _kpmgBlobAccountKey;
    
    return kpmgBlobAccountKey;
}

/// <summary>
/// Blob container name
/// </summary>
/// <param name = "_kpmgBlobContainerName">Blob container name</param>
/// <returns>Record of type str</returns>
public str parmKPMGBlobContainerName(str _kpmgBlobContainerName = kpmgBlobContainerName)
{
    kpmgBlobContainerName = _kpmgBlobContainerName;
    
    return kpmgBlobContainerName;
}

    /// <summary>
    /// Send email none interactively with retry.
    /// </summary>
    /// <param name = "emailContract">Email contract from printer settings.</param>
    /// <param name = "reportBytes">Byte data of rendered report.</param>
    /// <param name = "fileName">The name of attached file.</param>
    /// <returns>True, if sending correctly, otherwise, False.</returns>
    public boolean emailReportWithRetry(SrsReportEMailDataContract emailContract, System.Byte[] reportBytes, str fileName)
    {
        if(this.parmKPMGFromAddress())
        {
            this.fromAddress    = this.parmKPMGFromAddress();
        }
        if(this.parmKPMGSysEmailContents())
        {
            emailContract.parmBody(this.parmKPMGSysEmailContents());
        }
        if(this.parmKPMGFileName())
        {
            fileName    = this.parmKPMGFileName();
        }
        if(this.parmKPMGSysEmailSubject())
        {
            emailContract.parmSubject(this.parmKPMGSysEmailSubject());
        }

        try
        {

            if(this.parmKPMGBlobAccountName() && this.parmKPMGBlobAccountKey() && reportBytes != null)
            {
                StorageCredentials  kpmgStorageCredentials   = new Microsoft.WindowsAzure.Storage.Auth.StorageCredentials(this.parmKPMGBlobAccountName(), this.parmKPMGBlobAccountKey());
                CloudStorageAccount kpmgCloudStorageAccount = new Microsoft.WindowsAzure.Storage.CloudStorageAccount(kpmgStorageCredentials, true);

                CloudBlobClient     kpmgBlobClient          = kpmgCloudStorageAccount.CreateCloudBlobClient();
                CloudBlobContainer  kpmgCloudBlobContainer  = kpmgBlobClient.GetContainerReference(this.parmKPMGBlobContainerName());
                CloudBlockBlob      kpmgCloudBlockBlob      = kpmgCloudBlobContainer.GetBlockBlobReference(this.parmKPMGFileName());
                System.IO.MemoryStream kpmgStream           = new System.IO.MemoryStream(reportBytes);
                kpmgCloudBlockBlob.UploadFromStream(kpmgStream, null, null, null);
            }
        }
        catch
        {
            // Show warning
            warning(strFmt("@KPMGAddOn:BlobUploadErrorMsg", this.parmKPMGFileName()));
        }
        
        if (CustFormletterDocument::find().METUnsentFTIEmailTo &&
            (!emailContract.parmTo() ||
            !SysEmailDistributor::validateEmails(emailContract.parmTo())))
        {
            SysIMailerNonInteractive mailer         = this.parmSysMailer();
            var                      messageBuilder = new SysMailerMessageBuilder();

            messageBuilder.setFrom(this.fromAddress)
                          .addTo(CustFormletterDocument::find().METUnsentFTIEmailTo)  
                          .setSubject("@KPMGAddOn:InvalidFTIEmail" + ': ' + emailContract.parmSubject())
                          .setBody(emailContract.parmBody())
                          .addAttachment(new System.IO.MemoryStream(reportBytes), fileName);
          
           mailer.sendNonInteractive(messageBuilder.getMessage());
        }

        return next emailReportWithRetry(emailContract, reportBytes, fileName);
    }
